    const WALL = '#dcdcd6', BAND = {c:'#4f6b80', m:1, fh:4.2, cw:3.2}, GL = {c:'#6f8ea2', glow:'#e6f0ff', gk:0.35};
    prismP(B.p('#a3a19a'), P, base, yD, false); pilesP(B.p('#77746d'), P, yD - 0.4, 10, 0.9);
    // main body: shopping levels, glazed terminal level, roof car park deck and its parapet
    prismP(B.p(WALL), main, yD, yD + 14.4, true); bandsP(B.p(BAND), main, yD + 1, yD + 14, 4.6, 2.6, 0.08);
    prismP(B.p(GL), offP(main, 0.8), yD + 14.4, yD + 20.4, true); mullP(B.p('#e6e7e4'), offP(main, 0.8), yD + 14.4, yD + 20.4, 3.6, 0.2, 0.06);
    prismP(B.p('#c9c8c2'), main, yD + 20.4, yD + 21.4); railP(B.p('#e0e0dc'), main, () => yD + 21.4, 1.2, 4, true);
    { const o = B.p('#f0efe8'), Q = offP(main, 4), bq = bbP(Q); for (let x = bq[0]; x < bq[2]; x += 6){ const z0 = bq[1], z1 = bq[3]; const ins = []; for (let z = z0; z <= z1; z += 1) if (inPoly(Q, x, z)) ins.push(z); if (ins.length > 4) quadP(o, [x, yD + 21.45, ins[0]], [x + 0.15, yD + 21.45, ins[0]], [x + 0.15, yD + 21.45, ins[ins.length-1]], [x, yD + 21.45, ins[ins.length-1]]); } }
    // the lower outline parts (podium round the main body)
